<script setup>
import {reactive,ref,watch,computed} from 'vue'
import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app'
import QuestionConfirmation from '../../components/QuestionConfirmation.vue'
import QuestionRecovery from '../../components/QuestionRecovery.vue'
import {ownerSession,clearOwnerSession} from '../../services/owner-session.js'
import {vehicleApi} from '../../services/vehicles.js'
import {exact} from '../../services/experience-publication.js'
import {createCommunityQuestionApi,QUESTION_CATEGORIES,CASE_STATES,SERVICE_STATES,validQuestionBody} from '../../services/community-questions.js'
import {createCommunityQuestionRecovery,pendingQuestion,createQuestionConfirmation} from '../../services/community-question-recovery.js'
import {initialDiagnosisState,createAsyncDiagnosisFlow} from '../../services/async-diagnosis.js'
import {imageRequestKey} from '../../services/private-images.js'
import {displayTime} from '../../services/reservations.js'
const state=reactive(initialDiagnosisState()),form=reactive({vehicle:0,category:'FAULT',text:'',consent:false}),vehiclePage=ref(1),routeValid=ref(true),preview=ref(null),confirmation=reactive({prompt:null}),api=createCommunityQuestionApi(),token=()=>ownerSession.accessToken
const recovery=createCommunityQuestionRecovery({actor:()=>ownerSession.actorId,role:()=> 'owner',scope:()=> 'create'}),gate=createQuestionConfirmation({state:confirmation,preview:()=>preview.value}),blocked=()=>state.busy||state.retry||state.kind==='storage'
const car=computed(()=>state.data?.cars?.list.find(v=>v.vehicle_id===form.vehicle))
async function load(t,p){const [cases,context,cars]=await Promise.allSettled([api.list(t,'owner',p),api.context(t),vehicleApi.list(t,vehiclePage.value)]);if(cases.status==='rejected')throw cases.reason;for(const r of [context,cars])if(r.status==='rejected'&&['unauthorized','forbidden','missing'].includes(r.reason.kind))throw r.reason;return {cases:cases.value,context:context.status==='fulfilled'?context.value:null,cars:cars.status==='fulfilled'?cars.value:null}}
const flow=createAsyncDiagnosisFlow({state,token,allowed:()=>routeValid.value,scope:()=>`owner:${ownerSession.actorId}:${form.vehicle}`,load,write:(t,a,n,b,k)=>api.write(t,'owner',a,n,b,k),newKey:imageRequestKey,recovery,confirm:gate.ask,onWritten:r=>{clearForm();uni.navigateTo({url:`/pages/community/question?role=owner&id=${r.case_id}`})}})
let visible=false
function clearForm(){Object.assign(form,{vehicle:0,category:'FAULT',text:'',consent:false});preview.value=null}
function reset(){gate.cancel();flow.reset();clearForm()}
function login(){clearOwnerSession();uni.navigateTo({url:'/pages/owner/index'})}
function choose(v){if(blocked()||!state.data?.cars?.list.includes(v))return;gate.cancel();flow.reset();clearForm();form.vehicle=v.vehicle_id;flow.load(state.page)}
function carsPage(p){if(blocked())return;reset();vehiclePage.value=p;flow.load(state.page)}
function send(){if(blocked())return;const ctx=state.data?.context,b={vehicle_id:form.vehicle,category:form.category,policy_id:ctx?.policy?.id,policy_revision:ctx?.policy?.revision,message:form.text.trim(),consent:form.consent};if(!ctx?.accepting||!car.value||!validQuestionBody(b,'create')){state.message='请核对受理状态、本人车辆、分类和文字，并明确确认共享用途。';return}preview.value={title:'确认提交私有问答',lines:[`车辆：${car.value.model_name}（编号${form.vehicle}）`,`分类：${QUESTION_CATEGORIES[form.category]}`,`受理政策 ${b.policy_id} · 版本 ${b.policy_revision}`,'仅向当前获派人员共享所选车型和以下文字；非实时答复，不共享档案、诊断或图片。',b.message]};flow.save('create',0,b)}
watch(()=>[token(),ownerSession.actorId],()=>{reset();vehiclePage.value=1;if(visible&&token()&&routeValid.value)flow.load()},{flush:'sync'})
watch(()=>state.kind,k=>{if(['unauthorized','forbidden','missing'].includes(k)){gate.cancel();clearForm()}},{flush:'sync'})
onLoad(q=>routeValid.value=exact(q||{},[]));onShow(()=>{visible=true;if(token()&&routeValid.value)flow.load()});function hide(){visible=false;reset()}onHide(hide);onUnload(hide)
</script>
<template><view class="reservation-page"><text class="reservation-title">我的私有车辆问答</text><text>独立运营人员非实时答复；问题与答复仅本人和当前获派人员可见。公开须另行授权审核。</text><text v-if="!routeValid">问答入口参数无效，请从本人入口重新进入。</text><button v-if="!token()" @tap="login">车主登录</button><button v-if="['unauthorized','forbidden'].includes(state.kind)" @tap="login">重新登录</button><text v-if="state.busy">正在核对本人问答…</text><QuestionRecovery :state="state" :flow="flow" :pending="pendingQuestion(recovery)"/><button :disabled="state.busy" @tap="flow.load(state.page)">刷新当前记录</button><template v-if="state.data"><view class="reservation-panel"><text class="reservation-heading">主动提交新问题</text><text>{{state.data.context?SERVICE_STATES[state.data.context.state]:'受理状态暂不可读取，仍可查看已有问答。'}}</text><text v-if="!state.data.cars">本人车辆暂不可读取，不显示空车辆或自动选择。</text><template v-if="state.data.context?.accepting&&state.data.cars"><text>选择本次车辆，切换会清空未提交文字。</text><button v-for="v in state.data.cars.list" :key="v.vehicle_id" :disabled="blocked()" @tap="choose(v)">{{form.vehicle===v.vehicle_id?'已选择 · ':''}}{{v.model_name}} {{v.plate_no_masked}}</button><text v-if="!state.data.cars.list.length">暂无本人车辆，请先录车。</text><button v-if="vehiclePage>1" :disabled="blocked()" @tap="carsPage(vehiclePage-1)">上一页车辆</button><button v-if="vehiclePage*20<state.data.cars.total" :disabled="blocked()" @tap="carsPage(vehiclePage+1)">下一页车辆</button><picker :range="Object.values(QUESTION_CATEGORIES)" :disabled="blocked()" @change="form.category=Object.keys(QUESTION_CATEGORIES)[Number($event.detail.value)]"><view>{{QUESTION_CATEGORIES[form.category]}}</view></picker><textarea v-model="form.text" maxlength="4000" :disabled="blocked()" placeholder="主动输入本次问题，最多2000字，不自动读取档案"/><checkbox-group @change="form.consent=$event.detail.value.includes('yes')"><label><checkbox value="yes" :checked="form.consent" :disabled="blocked()"/>确认仅分享所选车型、分类和本次文字，用于私有运营答复</label></checkbox-group><button :disabled="blocked()||!car" @tap="send">预览并确认提交</button></template></view><text class="reservation-heading">本人历史问答</text><text>车辆转移不转移问答；此处按原提问人读取，补充仍核验原车当前归属。</text><text v-if="!state.data.cases.items.length">暂无本人问答。</text><view v-for="c in state.data.cases.items" :key="c.case_id" class="reservation-panel"><text>问答 {{c.case_id}} · {{CASE_STATES[c.status]}} · {{displayTime(c.updated_at)}}</text><button :disabled="state.busy" @tap="uni.navigateTo({url:`/pages/community/question?role=owner&id=${c.case_id}`})">查看本人问题与答复</button></view><button v-if="state.page>1" :disabled="blocked()" @tap="flow.load(state.page-1)">上一页问答</button><button v-if="state.page*20<state.data.cases.total" :disabled="blocked()" @tap="flow.load(state.page+1)">下一页问答</button></template><QuestionConfirmation :prompt="confirmation.prompt" @answer="gate.settle"/></view></template>
